pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0) && recipient != address(c) && recipient != address(this));
        vm.deal(address(c), 1 ether);
        bool ok;
        try c.getFirstWithdrawalBonus(recipient) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok ? address(recipient).balance == 100 : true);
    }
}
